style.css:
@-moz-document domain("docs.google.com") {
/* Body background */
  body, .docs-titlebar {
    background-color: #f0f8ff; /* soft light blue */
    font-family: 'Inter', sans-serif; /* modern font */
  }

  /* Toolbar background */
  .docs-material, .docs-titlebar {
    background-color: #d3dbe8; /* slightly darker blue */
  }

  /* Toolbar icons */
  .docs-titlebar-buttons .goog-toolbar-button {
    color: #505d69; /* darker gray for contrast */
  }

  /* Document background */
  .kix-appview, .kix-page {
    background-color: #ffffff; /* pure white for clarity */
    color: #333333; /* dark text for readability */
  }

  /* Sidebar and menu */
  .docs-homescreen, .docs-menu {
    background-color: #d3dbe8;
    color: #333333;
  }

  /* Font customization */
  * {
    font-family: 'Inter', sans-serif !important; /* Ensuring font consistency */
  }

  /* Text selection */
  ::selection {
    background-color: #a8c0ff; /* light blue for selected text */
    color: #333333; /* contrasting text color */
  }

  /* Links */
  a {
    color: #3466a3; /* subtle blue for links */
  }

  /* Highlighted buttons */
  .goog-toolbar-button-hover, .goog-toolbar-button-active {
    background-color: #e0eaf5; /* light blue background for button hover */
    color: #505d69;
  }

  /* Page border */
  .kix-page {
    border: 1px solid #d1d5db; /* very light gray border */
  }
}
